import { readFileSync } from "node:fs";
import { join } from "node:path";
import type { QuranDataset } from "@/core/verify/quran-matcher";
import { QuranMatcher } from "@/core/verify/quran-matcher";
import type { SavedItem } from "@/core/types";

/** Verbatim Tanzil subset generated by `pnpm fetch:quran --fixture`. */
export const quranFixture: QuranDataset = JSON.parse(
  readFileSync(join(import.meta.dirname, "../fixtures/quran-subset.json"), "utf8"),
);

export const quranMatcher = new QuranMatcher(quranFixture);

export function verse(surah: number, ayah: number) {
  const v = quranFixture.verses.find((x) => x.surah === surah && x.ayah === ayah);
  if (!v) throw new Error(`Verse ${surah}:${ayah} missing from fixture`);
  return v;
}

export function makeItem(overrides: Partial<SavedItem> = {}): SavedItem {
  const now = "2026-10-01T10:00:00.000Z";
  return {
    id: overrides.id ?? Math.random().toString(36).slice(2),
    title: "Test item",
    contentType: "dua",
    subcategory: "other",
    arabicText: "",
    englishText: "",
    transliteration: null,
    ocrRawText: null,
    ocrConfidence: null,
    sourceText: null,
    verification: { status: "unverified", notes: [], checkedAt: now },
    screenshotKey: null,
    tags: [],
    notes: "",
    isFavorite: false,
    reminderTime: null,
    practiceCount: 0,
    createdAt: now,
    updatedAt: now,
    lastReviewedAt: null,
    ...overrides,
  };
}
